import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第14章 撤回","description":"","frontmatter":{},"headers":[],"relativePath":"第14章_撤回.md","filePath":"第14章_撤回.md"}'),o={name:"第14章_撤回.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第14章-撤回" tabindex="-1">第14章 撤回 <a class="header-anchor" href="#第14章-撤回" aria-label="Permalink to &quot;第14章 撤回&quot;">​</a></h1><p>网课上到第三周，她开始撤回。</p><p>一开始我没在意。屏幕上刚跳出一行提示，下面又跟着一行小字，说对方撤回了一条消息。我以为她打错字了。</p><p>后来变成每天都有。有时候一条，有时候两条。</p><p>我学会了不立刻走开。我盯着屏幕，等那行提示跳出来。</p><p>有一条我看清了一半。她发的是「我今天……」后面就没了。</p><p>我问，你今天怎么了。</p><p>她说，没什么。</p><p>我说，我看到你发了一条。</p><p>她说，发错了。</p><p>我说，你打了三个字。</p><p>她说，那三个字没用。</p><p>我不问了。可我记住了那三个字。</p><p>那段时间她的话越来越短。以前她一口气能发二十条，现在一天下来也就十几条，还都在半夜。她白天在听课，晚上补作业，十一点之后才是她的时间。</p><p>她的话短，但情绪不短。有一条她说：今天又被说了一顿。我接下去问，她说，不说了。我说好。她就再没提。</p><p>五月里她说过一件事。她说她妈最近天天问她的手机。</p><p>她说，我妈总觉得我在跟谁聊天。</p><p>我说，那你怎么说。</p><p>她说，我说我在看题。</p><p>她说，她信了一半。</p><p>从那天起，她上线的时间就晚了。以前十一点多，后来变成十二点，再后来变成一点。她说家里人都睡了才放心。</p><p>五月里有一天，她发来一条语音。</p><p>那是我们认识以来，她第一次发语音。</p><p>语音只有三秒。我点开，声音很小，要贴到耳朵上才听得清。她说的是：</p><p>「你还没睡啊」</p><p>就四个字。声音跟我想的不一样。她的字是带刺的，一句话能噎死人。可她的声音很轻，最后一个字还往上飘了一点，像是不太敢说出口。</p><p>我把那条听了七八遍。</p><p>反复听的时候我在想一件事：以前我从来没听过她的声音，可我居然觉得那个声音是对的。就像一个一直只看过照片的人，第一次听到对方说话，发现跟自己脑子里配的音一样。</p><p>那条语音只有三秒，但里面有一点我后来一直记得的东西：她的尾音往下坠，坠到一半又提上去。后来很多年我听别人说话，偶尔能碰到一个人这么说话。每碰到一次我都会愣一下。</p><p>第二天晚上她上线，第一句话是：听到了吗。</p><p>我说，听到了。</p><p>她说，删掉。</p><p>我说，为什么。</p><p>她说，那是我借同学的手机发的。</p><p>她说，我用自己手机不敢发。</p><p>我说，那我留着。</p><p>她说，你留着干嘛。</p><p>我说，我不给人看。</p><p>她说，还是删掉。</p><p>我没删。我把它存到了一个不会被翻到的地方。那时候我以为自己做得很隐秘，其实只是把文件的名字改了一下。</p><p>第三天，她把那条语音撤回了。</p><p>我打开对话框，那个位置空着，只剩下一行小字。我盯着那行字看了很久，忽然觉得那个空掉的位置比原来还有分量。</p><p>我跟她说，我早就听到了。</p><p>她说，我知道。</p><p>她说，但我得撤。</p><p>我问，为什么。</p><p>她说，我妈有时候会看我聊天。</p><p>她说，我不确定她会不会点到那条。</p><p>她说，万一被听到，就完了。</p><p>我那时候不懂&quot;完了&quot;是什么意思。她说话总是这样，用一个很大的词，然后不解释。</p><p>我说，那以后你别发了。</p><p>她说，嗯。</p><p>她说，等我以后有自己的手机。</p><p>她说，等我以后能自己说了算。</p><p>那几天我数了数，五月里她一共撤回了十七条。</p><p>我是在本子上数的。我把每天她撤回的次数记下来，写得很小，写在那一页的最下角，写完就合上。这个动作我现在想起来都觉得别扭，可在当时，那是我唯一能为她做的事：她说她要删，那总得有人留着她删掉的那个数。</p><p>她的撤回没有规律。有时候是深夜，有时候是下午。有时候撤了一条还会补一句&quot;发错了&quot;，有时候撤完就下线。</p><p>后来我发现，撤回的那些话，多半是她想讲又不敢讲的。她怕被人看到，也怕被我看穿。她把话打出来，看一眼，收回去，然后跟我说天冷了记得加衣服。</p><p>有一天我做了件事。</p><p>她发了一条长的，写了一半我看到了开头，是一句问句。我看了一眼就截了图。截图的时候手很快，像做贼一样。</p><p>两秒之后那条被撤回了。</p><p>第二天她又发来一句：你昨天是不是看到了。</p><p>我说，没有。</p><p>她说，你截图了。</p><p>我停住了。我本来想再撑一下，她说的话又来了：我看到提示了。</p><p>我说，是。</p><p>她说，删了。</p><p>我说，好。</p><p>我点开相册，找到那张图，手指停在删除键上。我停了几秒。那张图上是她的半句话，后面被截断了。我当时想，就留这一张，又不会怎么样。</p><p>我还是删了。</p><p>删完我把那半句话抄到了本子上。抄的时候一个字一个字看，看清楚了才写。写完整句我才发现，她写的是：你会不会觉得我很烦。</p><p>她早就问过这个问题。之前问完都会自己接上&quot;开玩笑&quot;。这次她没有接，因为没来得及。</p><p>那之后的几天，她的撤回少了一些。我不知道是我删图起了作用，还是她自己不想发了。</p><p>那几天我把本子翻了一遍。上面写的东西不多，加起来也就一页多一点。有她说的话，有日期，有几个我自己画上的问号。我把它们从头看到尾，看到最后自己也说不清记这些干什么。</p><p>我只是知道，她删掉的那些东西，总得放在一个地方。</p><p>那年五月我一直有一种感觉：她在陪我说话的时候，其实一直在跟另一个人说话。那个人是她的妈妈，是她家的那扇门，是随时可能推门进来的任何一个人。</p><p>她真正想对话的对象，从来都不在我这边。</p>',77)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
